func longestValidParentheses(s string) int {
    stack := []int{-1} // 栈底哨兵：最后一个未匹配右括号的位置
    res := 0
    for i := 0; i < len(s); i++ {
        if s[i] == '(' {
            stack = append(stack, i)
        } else {
            stack = stack[:len(stack)-1]
            if len(stack) == 0 {
                // 栈空，当前 ')' 成为新的分界线
                stack = append(stack, i)
            } else {
                res = max(res, i-stack[len(stack)-1])
            }
        }
    }
    return res
}

func longestValidParentheses(s string) int {
    dp := make([]int, len(s))
    res := 0
    for i := 1; i < len(s); i++ {
        if s[i] == ')' {
            if s[i-1] == '(' {
                // ...()
                dp[i] = 2
                if i >= 2 {
                    dp[i] += dp[i-2]
                }
            } else if dp[i-1] > 0 {
                // ...))
                j := i - 1 - dp[i-1] // 与当前 ')' 可能配对的位置
                if j >= 0 && s[j] == '(' {
                    dp[i] = dp[i-1] + 2
                    if j >= 1 {
                        dp[i] += dp[j-1] // 拼接之前的有效段
                    }
                }
            }
            res = max(res, dp[i])
        }
    }
    return res
}
